Mat augmented(const Mat&L,const vector<int>&rr,const vector<int>&cc,const vector<int>&ff){Mat A(18,vector<P>(20));for(int i=0;i<18;i++){for(int j=0;j<18;j++)A[i][j]=L[rr[i]][cc[j]];for(int j=0;j<2;j++)A[i][18+j]=L[rr[i]][ff[j]];}return A;}
P det3(const Mat&B){P z;for(int a=0;a<3;a++){int j=(a+1)%3,k=(a+2)%3;z=add(z,mul(B[0][a],add(mul(B[1][j],B[2][k]),scale(mul(B[1][k],B[2][j]),-1))));}return z;}
